}

export function serializeStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const records = rows.map((row) => [
        dataset,
        row.chartRole,
        row.available,
        row.grouping,
        row.utcBucketStart ?? '',
        row.utcBucketEnd ?? '',
        row.identity,
        row.provider ?? '',
        row.limitId ?? '',
        row.windowId ?? '',
        row.agent ?? '',
        row.actionType ?? '',
        row.actionId ?? '',
