    if (bucketSamples.length === 0) {
        return [emptyTimeRow(context, controls.performanceGranularity, 'primary', controls.performanceMetric, unit)];
    }
    const groups = new Map<string, EligibleSample[]>();
    for (const sample of bucketSamples) {
